import{_ as r,C as n,c as i,o as s,a3 as e,G as a}from"./chunks/framework.Dokpd4od.js";const y=JSON.parse('{"title":"Two-factor authentication","description":"","frontmatter":{},"headers":[],"relativePath":"master/general-settings/users/two-factor-authentication.md","filePath":"master/general-settings/users/two-factor-authentication.md","lastUpdated":1792041590000}'),c={name:"master/general-settings/users/two-factor-authentication.md"};function l(u,t,h,p,d,f){const o=n("ImagePopup");return s(),i("div",null,[t[0]||(t[0]=e('<h1 id="two-factor-authentication" tabindex="-1">Two-factor authentication <a class="header-anchor" href="#two-factor-authentication" aria-label="Permalink to &quot;Two-factor authentication&quot;">​</a></h1><p><strong>Two-factor authentication</strong> adds a second step to your sign-in. After your password, you enter a 6-digit code from an authenticator app on your phone. Even if someone learns your password, they cannot sign in without your phone.</p><blockquote><p><strong>In simple words:</strong> To sign in you need two things: your password and your phone.</p></blockquote><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Install an authenticator app on your phone. Any app that makes 6-digit time-based codes works.</p><h2 id="turn-on-two-factor-authentication" tabindex="-1">Turn on two-factor authentication <a class="header-anchor" href="#turn-on-two-factor-authentication" aria-label="Permalink to &quot;Turn on two-factor authentication&quot;">​</a></h2><ol><li>Open your <a href="./profile.html">profile</a>.</li><li>In the <strong>Authenticator app</strong> section, click <strong>Set up</strong>. The status shows <strong>Disabled</strong> until you finish.</li><li>Scan the QR code with your authenticator app. If you cannot scan it, enter the code shown under the picture by hand.</li><li>Enter the 6-digit code that the app shows.</li><li>Click <strong>Enable authenticator app</strong>.</li><li>Save your <strong>recovery codes</strong> in a safe place. Aureus shows them only once.</li></ol><p>The status changes to <strong>Enabled</strong>.</p>',8)),a(o,{src:"/images1/general-settings/two_factor_section.png",alt:"Authenticator app section on the profile page, status Disabled with the Set up button"}),a(o,{src:"/images1/general-settings/two_factor_setup_modal.png",alt:"Set up authenticator app window with QR code and 6-digit code field"}),t[1]||(t[1]=e('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Recovery codes are your way back in if you lose your phone. Store them somewhere safe. Aureus shows them only once.</p></div><h2 id="sign-in-with-a-code" tabindex="-1">Sign in with a code <a class="header-anchor" href="#sign-in-with-a-code" aria-label="Permalink to &quot;Sign in with a code&quot;">​</a></h2><ol><li>Enter your email and password as usual.</li><li>When Aureus asks, enter the 6-digit code from your authenticator app.</li></ol><p>If you cannot use your phone, click <strong>Use a recovery code instead</strong> and enter one of your recovery codes.</p><h2 id="get-new-recovery-codes" tabindex="-1">Get new recovery codes <a class="header-anchor" href="#get-new-recovery-codes" aria-label="Permalink to &quot;Get new recovery codes&quot;">​</a></h2><ol><li>Open your <a href="./profile.html">profile</a>.</li><li>In the <strong>Authenticator app</strong> section, click <strong>Regenerate recovery codes</strong>.</li><li>Enter the 6-digit code from your app, or your current password.</li><li>Click <strong>Regenerate recovery codes</strong>.</li><li>Save the new codes. The old codes stop working at once.</li></ol><h2 id="turn-off-two-factor-authentication" tabindex="-1">Turn off two-factor authentication <a class="header-anchor" href="#turn-off-two-factor-authentication" aria-label="Permalink to &quot;Turn off two-factor authentication&quot;">​</a></h2><ol><li>Open your <a href="./profile.html">profile</a>.</li><li>In the <strong>Authenticator app</strong> section, click <strong>Turn off</strong>.</li><li>Enter the 6-digit code from your app, or click <strong>Use a recovery code instead</strong>.</li><li>Click <strong>Disable authenticator app</strong>.</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Turning it off removes the extra layer of security from your account. Keep it on unless you have a reason to turn it off.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./profile.html">Your profile</a></li><li><a href="./users.html">Users</a></li></ul>',11))])}const w=r(c,[["render",l]]);export{y as __pageData,w as default};
